#!/usr/bin/env node
/* SUITE: Passkey 认证全流程（Playwright CDP 虚拟认证器，无头、无需真人）
 *
 * 覆盖 case：
 *  注册：新用户注册 → 会话建立 → 可访问受保护 API
 *  注册：重复用户名 → 400
 *  Key：登录态下创建 notify:send / notify:receive Key（真实 API）→ 各 scope 生效
 *  登录：登出后用已注册 Passkey 重新登录 → 会话恢复
 *  登出：logout → 会话失效 → 401
 *  登录：未注册用户登录 → 400/401
 */
import { chromium } from "playwright-core";
import * as H from "../lib/harness.mjs";

const RP = "localhost";
let server, browser, ctx, page, cdp;
const username = "auth_" + Date.now();

async function webauthnRegister(name) {
	return page.evaluate(async ({ base, name }) => {
		const b64 = (s) => { s = s.replace(/-/g, "+").replace(/_/g, "/"); const b = atob(s + "=".repeat((4 - s.length % 4) % 4)); return Uint8Array.from(b, (c) => c.charCodeAt(0)).buffer; };
		const b64u = (buf) => { const a = new Uint8Array(buf); let s = ""; for (const c of a) s += String.fromCharCode(c); return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, ""); };
		const o = await (await fetch(base + "/v1/auth/register/options", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ username: name, displayName: name }) })).json();
		const pk = o.publicKey || o;
		pk.challenge = b64(pk.challenge);
		if (pk.user?.id) pk.user.id = b64(pk.user.id);
		if (pk.excludeCredentials) pk.excludeCredentials = pk.excludeCredentials.map((c) => ({ ...c, id: b64(c.id) }));
		const cred = await navigator.credentials.create({ publicKey: pk });
		const payload = { id: cred.id, rawId: b64u(cred.rawId), type: cred.type, response: { clientDataJSON: b64u(cred.response.clientDataJSON), attestationObject: b64u(cred.response.attestationObject) } };
		const r = await fetch(base + "/v1/auth/register?username=" + encodeURIComponent(name), { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) });
