/* ================= 数据层 ================= */
// 统一通知结构（兼容后端 Message / 契约返回）
function normalize(n, i) {
  const payload = n.payload ? safeParse(n.payload) : n;
  return {
    id: n.id || n.ID || "n" + i,
    status: n.status || "info",
    title: n.title || "（无标题）",
    body: n.body || "",
    link: n.link || payload.link || "",
    agent: payload.agentId || payload.agent || "agent",
    project: payload.cwd || payload.project || "—",
    duration: payload.durationMs ? Math.round(payload.durationMs / 1000) : payload.duration || 0,
    model: payload.model || "—",
    sessionId: payload.sessionId || "—",
    time: timeAgo(n.created_at || n.createdAt || n.time),
    delivered: n.delivered != null ? n.delivered : (n.delivered_count != null ? n.delivered_count : 0),
    total: n.total != null ? n.total : (n.device_count != null ? n.device_count : 0),
  };
}

