function normalize(n, i) {
  const payload = n.Payload ? safeParse(n.Payload) : n.payload ? safeParse(n.payload) : n;
  return {
    id: n.id || n.ID || "n" + i,
    status: n.status || n.Status || "info",
    title: n.title || n.Title || "（无标题）",
